BUNDLE_BASE64=''
EXPECTED='ebc6c6439f29bdffd2b2d5cefade592636ed93e5309cdc607ce2dc0da2807f1d'
PLAN_B64=''
AUTH_B64=''
PLAN_SHA='256dbf22a82600ed78212e1f862669b62cf1cea49d79559c3addf31bf7ea6ef6'

import base64, datetime as dt, hashlib, io, json, os, pathlib, platform, socket, subprocess, tarfile, tempfile
def now(): return dt.datetime.now(dt.timezone.utc).isoformat()
def workers():
    found=[]
    for p in pathlib.Path('/proc').glob('[0-9]*/comm'):
        try:
            if p.read_text().strip()=='Runner.Worker':found.append(int(p.parent.name))
        except (FileNotFoundError,ProcessLookupError):pass
    return found
def clean_host():
    assert socket.gethostname()=='cicd-runner01' and os.getuid()==1000 and platform.machine()=='x86_64','WRONG_HOST'
    assert not workers(),'RUNNER_WORKER_ACTIVE'
    p=subprocess.run(['podman','ps','-a','--format','json'],capture_output=True,text=True,timeout=8)
    assert p.returncode==0 and json.loads(p.stdout)==[],'CONTAINERS_EXIST'
    p=subprocess.run(['ss','-H','-ltn','sport = :18081'],capture_output=True,text=True,timeout=5)
    assert p.returncode==0 and not p.stdout.strip(),'PORT_OCCUPIED'
    return {'hostname':socket.gethostname(),'uid':os.getuid(),'arch':platform.machine(),'worker_count':0,'container_count':0,'port18081_empty':True,'at_utc':now()}
os.umask(0o077)
result={'operation':'STAGE_AND_FIXTURE_HELPER_ONLY','started_at_utc':now(),'images_loaded_or_pulled':False,'runtime_containers_created':False,'actual_run_claim_created':False}
home=pathlib.Path('/home/server01_cicd-runner')
name='FDS_D03_Preparation_016390855fce'
dest=home/name
pre=None
try:
    result['before']=clean_host()
    raw=base64.b64decode(BUNDLE_BASE64,validate=True)
    assert hashlib.sha256(raw).hexdigest()==EXPECTED,'ARCHIVE_SHA_MISMATCH'
    assert not dest.exists() and not dest.is_symlink(),'TARGET_ALREADY_EXISTS'
    archive=home/(name+'.tar.gz')
    assert not archive.exists() and not archive.is_symlink(),'ARCHIVE_ALREADY_EXISTS'
    entries={}
    with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as tf:
        for member in tf.getmembers():
            path=pathlib.PurePosixPath(member.name)
            assert path.parts[0]==name and not path.is_absolute() and '..' not in path.parts and (member.isfile() or member.isdir()),'UNSAFE_MEMBER'
            assert member.name not in entries,'DUPLICATE_MEMBER'
            if member.isfile():entries[member.name]=tf.extractfile(member).read()
    manifest=entries[name+'/SHA256SUMS'].decode()
    checked=[]
    for line in manifest.splitlines():
        sha,rel=line.split('  ',1)
        assert hashlib.sha256(entries[name+'/'+rel]).hexdigest()==sha,'MANIFEST_MISMATCH'
        checked.append(rel)
    assert len(checked)==16 and len(entries)==17,'UNEXPECTED_FILE_COUNT'
    with archive.open('xb') as f:f.write(raw)
    dest.mkdir(mode=0o700)
    for member,content in entries.items():
        rel=pathlib.PurePosixPath(member).relative_to(name)
        target=dest.joinpath(*rel.parts)
        target.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
        with target.open('xb') as f:f.write(content)
        assert hashlib.sha256(target.read_bytes()).hexdigest()==hashlib.sha256(content).hexdigest()
    result['bundle']={'directory':str(dest),'archive':str(archive),'sha256':EXPECTED,'files':len(entries),'manifest_verified':len(checked)}
    provenance=json.loads((dest/'SOURCE_PROVENANCE.json').read_text())
    for entry in provenance['files']:
        assert hashlib.sha256((dest/'source'/entry['path']).read_bytes()).hexdigest()==entry['sha256']
    result['source_files_verified']=len(provenance['files'])
    result['helper_entry']=clean_host()
    pre=pathlib.Path(tempfile.mkdtemp(prefix='FDS_D03_Precheck.',dir=home))
    result['precheck_directory']=str(pre)
    argv=['python3','-B','-m','unittest','-v','tools.tests.test_d03_lab.StagedInvocation.test_staged_probe_reaches_loopback_fixture','tools.tests.test_d03_lab.FixtureWireBehavior.test_lab_helper_get_and_post_reach_actual_fixture']
    (pre/'started_at.txt').write_text(now()+'\n')
    (pre/'hostname.txt').write_text(socket.gethostname()+'\n')
    (pre/'identity.txt').write_text(subprocess.check_output(['id'],text=True))
    (pre/'command.json').write_text(json.dumps({'argv':argv,'cwd':str(dest/'source'),'bundle_sha256':EXPECTED,'merge_commit':provenance['merge_commit']},indent=2)+'\n')
    p=subprocess.run(argv,cwd=dest/'source',capture_output=True,timeout=20)
    (pre/'stdout.txt').write_bytes(p.stdout);(pre/'stderr.txt').write_bytes(p.stderr)
    (pre/'rc.txt').write_text(str(p.returncode)+'\n');(pre/'finished_at.txt').write_text(now()+'\n')
    result['helper']={'argv':argv,'rc':p.returncode,'stdout':p.stdout.decode(),'stderr':p.stderr.decode()}
    result['after']=clean_host()
    assert p.returncode==0,'HELPER_TEST_FAILED'
    result['status']='HELPER_PASS_RUNTIME_NOT_RUN'
except Exception as e:
    result['status']='PREPARATION_STOP'
    result['error_type']=type(e).__name__;result['error']=str(e)
result['finished_at_utc']=now()
if pre is not None:
    (pre/'result.json').write_text(json.dumps(result,indent=2)+'\n')
    (pre/'SHA256SUMS').write_text(''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.name+'\n' for p in sorted(pre.iterdir()) if p.is_file()))
if result['status']=='HELPER_PASS_RUNTIME_NOT_RUN':
    plan_raw=base64.b64decode(PLAN_B64);auth_raw=base64.b64decode(AUTH_B64)
    assert hashlib.sha256(plan_raw).hexdigest()==PLAN_SHA
    decisions=home/'FDS_D03_Decisions_202610150000'
    decisions.mkdir(mode=0o700)
    for filename,content in [('plan.json',plan_raw),('authorization.json',auth_raw)]:
        with (decisions/filename).open('xb') as f:f.write(content)
    result['decision_directory']=str(decisions)
    result['plan_sha256']=PLAN_SHA
print(json.dumps(result))
